(p/'foundation-browser-result.json').write_text(json.dumps(results,indent=2));print(json.dumps([{'file':x['file'],'wholeGLBByteExact':x['wholeGLBByteExact'],'topologyPass':x['browserTopology']['pass']} for x in results]))
